### Sidebar.tsx
```tsx
import { useState } from 'react';
import { UserIcon, CreditCardIcon, TeamIcon, BellIcon, LockIcon } from 'lucide-react';

export interface SidebarLink {
  id: string;
  label: string;
  icon: React.ReactNode;
}

export interface SidebarProps {
  links: SidebarLink[];
  activeLink: string;
  onLinkClick: (id: string) => void;
}

export default function Sidebar({ links, activeLink, onLinkClick }: SidebarProps) {
  return (
    <aside className="w-64 bg-white border-r border-gray-200 flex flex-col">
      <div className="p-6 border-b border-gray-100">
        <h2 className="text-xl font-semibold text-gray-900">Settings</h2>
      </div>
      <nav className="flex-1 p-4 overflow-y-auto">
        {links.map((link) => (
          <button
            key={link.id}
            onClick={() => onLinkClick(link.id)}
            className={`flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-medium transition-all duration-200
              ${activeLink === link.id
                ? 'bg-accent text-white'
                : 'text-gray-700 hover:bg-gray-100 hover:text-gray-900'
              }
            `}
          >
            <div className="flex-shrink-0">{link.icon}</div>
            <span>{link.label}</span>
          </button>
        ))}
      </nav>
      <footer className="p-4 border-t border-gray-100 text-sm text-gray-500">
        <p>Logged in as: Alex Johnson</p>
      </footer>
    </aside>
  );
}
```

